import 'package:firebase_core/firebase_core.dart';
import 'package:firebase_messaging/firebase_messaging.dart';
import 'package:flutter/material.dart';
import 'package:flutter_riverpod/flutter_riverpod.dart';
import 'package:go_router/go_router.dart';

import 'core/router/app_router.dart';
import 'core/theme/app_theme.dart';
import 'firebase_options.dart';
import 'providers/auth_provider.dart';
import 'services/push_notification_service.dart';

Future<void> main() async {
  WidgetsFlutterBinding.ensureInitialized();

  // Requires lib/firebase_options.dart, generated by running
  // `flutterfire configure` against your own Firebase project (see
  // firebase/README.md and docs/LIMITATIONS.md). This file is
  // intentionally not committed with placeholder values - a fake config
  // here would either fail to compile or silently point at a project
  // that doesn't exist, which is exactly what the project spec forbids.
  //
  // On Android specifically (real bug hit during first physical-device
  // run): the Google Services Gradle plugin reads android/app/
  // google-services.json and auto-initializes a native "[DEFAULT]"
  // FirebaseApp before Dart's main() ever runs. Calling
  // Firebase.initializeApp() here then collides with that already-
  // existing app and throws [core/duplicate-app] - uncaught, this
  // silently aborted main() before runApp(), which is why the app got
  // stuck on the native splash screen with no visible error. Android's
  // auto-initialized app already points at the same project
  // (campus-a4087, from that same google-services.json), so there is
  // nothing to actually fix here - just don't treat "it's already
  // initialized" as a fatal error. Web/iOS have no such native
  // auto-init, so this exception never fires there.
  try {
    await Firebase.initializeApp(options: DefaultFirebaseOptions.currentPlatform);
  } on FirebaseException catch (e) {
    if (e.code != 'duplicate-app') rethrow;
  }

  // Must be registered before runApp() - see push_notification_service.dart
  // for why this exists (background/terminated FCM delivery).
  FirebaseMessaging.onBackgroundMessage(firebaseMessagingBackgroundHandler);

  runApp(const ProviderScope(child: SecureCampusApp()));
}

final _scaffoldMessengerKey = GlobalKey<ScaffoldMessengerState>();

class SecureCampusApp extends ConsumerWidget {
  const SecureCampusApp({super.key});

  @override
  Widget build(BuildContext context, WidgetRef ref) {
    final GoRouter router = ref.watch(routerProvider);

    // Foreground FCM handling (fixed after audit - see
    // docs/AUDIT_REPORT.md §19/"Notifications"): the OS does not show a
    // banner for notification-type pushes while the app is open, so this
    // is what makes one actually appear. The underlying Firestore
    // notification doc (and therefore the in-app Notification Center's
    // unread count) is already live via Firestore streaming regardless
    // of whether this fires - this only adds the immediate on-screen banner.
    ref.listen(foregroundMessageProvider, (previous, next) {
      final message = next.valueOrNull;
      final notification = message?.notification;
      if (notification == null) return;
      _scaffoldMessengerKey.currentState?.showSnackBar(
        SnackBar(
          content: Text('${notification.title ?? 'Notification'}: ${notification.body ?? ''}'),
          duration: const Duration(seconds: 5),
          behavior: SnackBarBehavior.floating,
        ),
      );
    });

    return MaterialApp.router(
      title: 'SecureCampus',
      debugShowCheckedModeBanner: false,
      theme: AppTheme.light(),
      scaffoldMessengerKey: _scaffoldMessengerKey,
      routerConfig: router,
    );
  }
}